   reply: {prompt: "Write what you tell the contractor and your note to Elias.", points: [["Elias approves it himself (over $5,000)", ["elias", "approval", "approve", "5,000", "5000"]], ["Written quote, license and insurance checked", ["quote", "license", "insurance", "written"]]]},
   why: "Any expense over $5,000 goes to Elias himself, never pre-approved or delegated, whatever the contractor says he said.",
