   reply: {prompt: "Write exactly how you reach Elias and what you say.", points: [["Interrupt him now (a genuine emergency)", ["now", "immediately", "interrupt", "call him", "phone"]], ["Keep trying Sarah too", ["sarah"]], ["The school, the nurse, and Leo's condition", ["school", "nurse", "leo", "hives", "reaction"]]]},
