   reply: {prompt: "Write the SOP's outline.", points: [["Numbered steps", ["step", "1.", "first"]], ["Who owns each step", ["owner", "responsible", "who"]], ["Reviewed and approved", ["review", "approve", "sign off", "sign-off"]]]},
