   q: "What do you do?",
   options: [["Flag it to Robert Hale (CFO) at once; don't adjust anything yourself", 1], ["Move $3,400 back from the operating account yourself", 0.2], ["Note it for the next audit", 0], ["Ask the bookkeeper about it next week", 0.1]],
   reply: {prompt: "Write your message to Robert Hale.", points: [["The trust account", ["trust"]], ["Client funds used for a firm expense", ["firm expense", "commingl", "client funds", "office", "supplies"]], ["To Robert Hale, now", ["robert", "hale", "cfo"]]]},
